#include <functional>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::move_only_function<int()> function = [] { return 7; };
    std::move_only_function<int()> other = [] { return 9; };
    function.swap(other);
    assert(function() == 9);
    other = std::move(function);
    assert(other() == 9);
}
